mapper.select:
select id, project_id, route_id, from_account_id, to_account_id, review_type, overall_score, content, created_at
from reviews
where id = #{id}

select id, project_id, route_id, from_account_id, to_account_id, review_type, overall_score, content, created_at
from reviews
where project_id = #{projectId}

select id, project_id, route_id, from_account_id, to_account_id, review_type, overall_score, content, created_at
from reviews
where route_id = #{routeId}

select id, project_id, route_id, from_account_id, to_account_id, review_type, overall_score, content, created_at
from reviews
where to_account_id = #{toAccountId}

select id, project_id, route_id, from_account_id, to_account_id, review_type, overall_score, content, created_at
from reviews
where from_account_id = #{fromAccountId}

select id, project_id, route_id, from_account_id, to_account_id, review_type, overall_score, content, created_at
from reviews
where review_type = #{reviewType}

select avg(overall_score)
from reviews
where to_account_id = #{toAccountId}
